"""ETL pipeline: extract from log files, transform, load to Parquet."""

from __future__ import annotations

import json
import logging
import re
from dataclasses import dataclass, field
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Callable

import pyarrow as pa
import pyarrow.parquet as pq

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(name)s - %(message)s",
)
log = logging.getLogger("log_etl")

# ---------------------------------------------------------------------------
# Transform registry
# ---------------------------------------------------------------------------

TRANSFORMS: dict[str, Callable] = {}


def register_transform(name: str):
    def wrapper(fn: Callable) -> Callable:
        TRANSFORMS[name] = fn
        return fn

    return wrapper


@register_transform("parse_timestamps")
def _parse_timestamps(
    rows: list[dict], field: str, formats: list[str], output_field: str = "timestamp"
) -> list[dict]:
    """Try multiple datetime formats and store as ISO string."""
    for row in rows:
        raw = row.get(field, "")
        if raw is None:
            continue
        raw = str(raw).strip()
        for fmt in formats:
            try:
                dt = datetime.strptime(raw, fmt)
                row[output_field] = dt.isoformat()
                break
            except ValueError:
                continue
    return rows


@register_transform("filter_rows")
def _filter_rows(rows: list[dict], conditions: dict[str, Any]) -> list[dict]:
    """Keep rows where every key == value in conditions."""
    return [r for r in rows if all(r.get(k) == v for k, v in conditions.items())]


@register_transform("filter_regex")
def _filter_regex(rows: list[dict], field: str, pattern: str) -> list[dict]:
    """Keep rows where field matches the regex pattern."""
    rx = re.compile(pattern)
    return [r for r in rows if rx.search(str(r.get(field, "")))]


@register_transform("exclude_regex")
def _exclude_regex(rows: list[dict], field: str, pattern: str) -> list[dict]:
    """Drop rows where field matches the regex pattern."""
    rx = re.compile(pattern)
    return [r for r in rows if not rx.search(str(r.get(field, "")))]


@register_transform("drop_fields")
def _drop_fields(rows: list[dict], fields: list[str]) -> list[dict]:
    drop = set(fields)
    return [{k: v for k, v in r.items() if k not in drop} for r in rows]


@register_transform("keep_fields")
def _keep_fields(rows: list[dict], fields: list[str]) -> list[dict]:
    keep = set(fields)
    return [{k: v for k, v in r.items() if k in keep} for r in rows]


@register_transform("rename_fields")
def _rename_fields(rows: list[dict], mapping: dict[str, str]) -> list[dict]:
    return [{mapping.get(k, k): v for k, v in row.items()} for row in rows]


@register_transform("cast_types")
def _cast_types(rows: list[dict], casts: dict[str, str]) -> list[dict]:
    casters: dict[str, Callable] = {
        "int": int,
        "float": float,
        "str": str,
        "bool": lambda v: v in (True, "true", "True", "1", 1),
    }
    result = []
    for row in rows:
        new_row = dict(row)
        for fname, target_type in casts.items():
            if fname in new_row and new_row[fname] is not None:
                try:
                    new_row[fname] = casters[target_type](new_row[fname])
                except (ValueError, TypeError):
                    new_row[fname] = None
        result.append(new_row)
    return result


@register_transform("add_field")
def _add_field(rows: list[dict], field_name: str, value: Any) -> list[dict]:
    for row in rows:
        row[field_name] = value
    return rows


@register_transform("extract_regex_groups")
def _extract_regex_groups(
    rows: list[dict], field: str, pattern: str, output_fields: list[str]
) -> list[dict]:
    """Extract named groups from a field using a regex and add as new fields."""
    rx = re.compile(pattern)
    for row in rows:
        m = rx.search(str(row.get(field, "")))
        if m:
            for i, name in enumerate(output_fields):
                row[name] = m.group(i + 1) if i + 1 <= len(m.groups()) else None
    return rows


@register_transform("severity_from_message")
def _severity_from_message(rows: list[dict], field: str = "message") -> list[dict]:
    """Infer severity from common log keywords if not already set."""
    patterns = [
        (re.compile(r"\b(FATAL|CRIT(ICAL)?)\b", re.I), "FATAL"),
        (re.compile(r"\b(ERROR|ERR)\b", re.I), "ERROR"),
        (re.compile(r"\bWARN(ING)?\b", re.I), "WARNING"),
        (re.compile(r"\bINFO\b", re.I), "INFO"),
        (re.compile(r"\bDEBUG\b", re.I), "DEBUG"),
        (re.compile(r"\bTRACE\b", re.I), "TRACE"),
    ]
    for row in rows:
        if row.get("severity"):
            continue
        msg = str(row.get(field, ""))
        for rx, sev in patterns:
            if rx.search(msg):
                row["severity"] = sev
                break
        else:
            row["severity"] = "UNKNOWN"
    return rows


@register_transform("sort_by")
def _sort_by(rows: list[dict], key: str, reverse: bool = False) -> list[dict]:
    return sorted(rows, key=lambda r: r.get(key) or "", reverse=reverse)


@register_transform("limit")
def _limit(rows: list[dict], n: int) -> list[dict]:
    return rows[:n]


@register_transform("deduplicate")
def _deduplicate(rows: list[dict], key: str | None = None) -> list[dict]:
    if key is None:
        seen: set = set()
        out = []
        for r in rows:
            sig = tuple(sorted(r.items()))
            if sig not in seen:
                seen.add(sig)
                out.append(r)
        return out
    seen_values: set = set()
    out = []
    for r in rows:
        val = r.get(key)
        if val not in seen_values:
            seen_values.add(val)
            out.append(r)
    return out


@register_transform("aggregate_counts")
def _aggregate_counts(rows: list[dict], group_by: str, output_field: str = "count") -> list[dict]:
    """Count rows per group_by value."""
    counts: dict[str, int] = {}
    for r in rows:
        key = str(r.get(group_by, ""))
        counts[key] = counts.get(key, 0) + 1
    return [{group_by: k, output_field: v} for k, v in sorted(counts.items())]


@register_transform("truncate_message")
def _truncate_message(rows: list[dict], field: str = "message", max_length: int = 500) -> list[dict]:
    for row in rows:
        val = row.get(field)
        if isinstance(val, str) and len(val) > max_length:
            row[field] = val[:max_length]
    return rows


# ---------------------------------------------------------------------------
# Log parsers
# ---------------------------------------------------------------------------

# Common log format:  127.0.0.1 - frank [10/Oct/2000:13:55:36 -0700] "GET /index.html HTTP/1.0" 200 2326
CLF_RE = re.compile(
    r'(?P<remote_host>\S+) \S+ (?P<user>\S+) '
    r'\[(?P<timestamp>[^\]]+)\] '
    r'"(?P<method>\S+) (?P<path>\S+) (?P<protocol>[^"]*)" '
    r'(?P<status>\d{3}) (?P<bytes>\S+)'
)

# Syslog: Jun 22 13:55:36 hostname service[pid]: message
SYSLOG_RE = re.compile(
    r'(?P<timestamp>\w{3}\s+\d{1,2}\s+\d{2}:\d{2}:\d{2})\s+'
    r'(?P<hostname>\S+)\s+'
    r'(?P<service>\S+?)(?:\[(?P<pid>\d+)\])?\s*:\s*'
    r'(?P<message>.*)'
)

# Generic key=value parser
KV_RE = re.compile(r'(?P<key>\w+)=(?P<value>"[^"]*"|\S+)')


def parse_json_log(line: str) -> dict[str, Any] | None:
    try:
        return json.loads(line)
    except json.JSONDecodeError:
        return None


def parse_clf_log(line: str) -> dict[str, Any] | None:
    m = CLF_RE.match(line)
    if not m:
        return None
    d = m.groupdict()
    d["status"] = int(d["status"])
    d["bytes"] = int(d["bytes"]) if d["bytes"] != "-" else 0
    return d


def parse_syslog(line: str) -> dict[str, Any] | None:
    m = SYSLOG_RE.match(line)
    if not m:
        return None
    d = m.groupdict()
    if d.get("pid"):
        d["pid"] = int(d["pid"])
    return d


def parse_kv_log(line: str) -> dict[str, Any] | None:
    pairs = KV_RE.findall(line)
    if len(pairs) < 2:
        return None
    d = {k: v.strip('"') for k, v in pairs}
    return d


def parse_plain_text(line: str, line_number: int) -> dict[str, Any]:
    return {"line_number": line_number, "message": line.rstrip("\n")}


PARSERS = {
    "json": parse_json_log,
    "clf": parse_clf_log,
    "apache": parse_clf_log,
    "syslog": parse_syslog,
    "key_value": parse_kv_log,
    "kv": parse_kv_log,
}


# ---------------------------------------------------------------------------
# Extractor
# ---------------------------------------------------------------------------


class LogExtractor:
    """Extract structured records from log files."""

    def __init__(self, log_format: str = "auto"):
        self.log_format = log_format

    def extract(self, paths: list[str], encoding: str = "utf-8") -> list[dict[str, Any]]:
        rows: list[dict[str, Any]] = []
        for pattern in paths:
            for filepath in sorted(Path().glob(pattern)):
                if not filepath.is_file():
                    continue
                log.info("Reading %s", filepath)
                rows.extend(self._parse_file(filepath, encoding))
        log.info("Extracted %d total rows", len(rows))
        return rows

    def _parse_file(self, path: Path, encoding: str) -> list[dict[str, Any]]:
        fmt = self.log_format
        rows: list[dict[str, Any]] = []
        with open(path, encoding=encoding, errors="replace") as f:
            for line_num, line in enumerate(f, 1):
                line = line.strip()
                if not line:
                    continue

                row = None
                if fmt == "auto":
                    for parser in PARSERS.values():
                        row = parser(line)
                        if row:
                            break
                    if row is None:
                        row = parse_plain_text(line, line_num)
                elif fmt in PARSERS:
                    row = PARSERS[fmt](line)
                    if row is None:
                        log.warning("Line %s:%d did not match format '%s', skipping", path, line_num, fmt)
                        continue
                else:
                    row = parse_plain_text(line, line_num)

                row["_source_file"] = str(path)
                row["_line_number"] = line_num
                rows.append(row)
        return rows


# ---------------------------------------------------------------------------
# Transformer
# ---------------------------------------------------------------------------


class Transformer:
    def transform(
        self, rows: list[dict], steps: list[dict[str, Any]]
    ) -> list[dict[str, Any]]:
        for step in steps:
            name = step["name"]
            params = {k: v for k, v in step.items() if k != "name"}
            fn = TRANSFORMS.get(name)
            if fn is None:
                raise ValueError(f"Unknown transform: {name!r}")
            rows = fn(rows, **params)
            log.debug("After '%s': %d rows", name, len(rows))
        return rows


# ---------------------------------------------------------------------------
# Loader
# ---------------------------------------------------------------------------


class ParquetLoader:
    """Write rows to Parquet files."""

    def __init__(self, output_dir: str = "etl_output"):
        self.output_dir = Path(output_dir)
        self.output_dir.mkdir(parents=True, exist_ok=True)

    def load(
        self,
        rows: list[dict[str, Any]],
        filename: str,
        partition_cols: list[str] | None = None,
    ) -> Path:
        if not rows:
            log.warning("No rows to load for %s", filename)
            return self.output_dir / filename

        table = pa.Table.from_pylist(rows)

        if partition_cols:
            # Partitioned write (Hive-style directories)
            base_dir = self.output_dir / filename.replace(".parquet", "")
            pq.write_to_dataset(table, root_path=str(base_dir), partition_cols=partition_cols)
            log.info("Loaded %d rows -> %s (partitioned by %s)", len(rows), base_dir, partition_cols)
            return base_dir
        else:
            path = self.output_dir / filename
            pq.write_table(table, path)
            log.info("Loaded %d rows -> %s", len(rows), path)
            return path


# ---------------------------------------------------------------------------
# Config
# ---------------------------------------------------------------------------


@dataclass
class LogETLTask:
    name: str
    input_paths: list[str]
    output_file: str
    log_format: str = "auto"
    encoding: str = "utf-8"
    transforms: list[dict[str, Any]] = field(default_factory=list)
    partition_cols: list[str] | None = None


@dataclass
class LogETLConfig:
    output_dir: str = "etl_output"
    tasks: list[LogETLTask] = field(default_factory=list)


def load_config(path: str) -> LogETLConfig:
    import yaml

    with open(path, encoding="utf-8") as f:
        raw = yaml.safe_load(f)
    tasks = []
    for t in raw.get("tasks", []):
        tasks.append(
            LogETLTask(
                name=t["name"],
                input_paths=t["input_paths"],
                output_file=t["output_file"],
                log_format=t.get("log_format", "auto"),
                encoding=t.get("encoding", "utf-8"),
                transforms=t.get("transforms", []),
                partition_cols=t.get("partition_cols"),
            )
        )
    return LogETLConfig(
        output_dir=raw.get("output_dir", "etl_output"),
        tasks=tasks,
    )


# ---------------------------------------------------------------------------
# Pipeline
# ---------------------------------------------------------------------------


class LogETLPipeline:
    """Orchestrates log extraction -> transform -> Parquet loading."""

    def __init__(self, config: LogETLConfig):
        self.config = config
        self.transformer = Transformer()
        self.loader = ParquetLoader(config.output_dir)

    @classmethod
    def from_config_file(cls, path: str) -> LogETLPipeline:
        return cls(load_config(path))

    def run(self) -> list[dict[str, Any]]:
        results = []
        for task in self.config.tasks:
            log.info("=== Task: %s ===", task.name)
            extractor = LogExtractor(log_format=task.log_format)
            rows = extractor.extract(task.input_paths, task.encoding)
            rows = self.transformer.transform(rows, task.transforms)
            out_path = self.loader.load(rows, task.output_file, task.partition_cols)
            results.append({
                "task": task.name,
                "rows_loaded": len(rows),
                "output": str(out_path),
            })
        log.info("Pipeline complete. %d task(s).", len(results))
        return results


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

if __name__ == "__main__":
    import sys

    config_path = sys.argv[1] if len(sys.argv) > 1 else "log_etl_config.yaml"
    pipeline = LogETLPipeline.from_config_file(config_path)
    summary = pipeline.run()
    print("\nLog ETL Summary:")
    for s in summary:
        print(f"  {s['task']}: {s['rows_loaded']} rows -> {s['output']}")
